<?php $this->layout('layouts/admin', ['title' => 'Đánh giá', 'pageTitle' => 'Quản lý đánh giá', 'activeMenu' => 'review']) ?>
<?php $this->start('page') ?>
<div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Tour</th><th>Điểm</th><th>Nội dung</th><th>Ngày tạo</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach($reviews as $review):?><tr><td>#<?= (int)$review['reviewId'] ?></td><td><strong><?= $this->e($review['customerName']) ?></strong><small class="d-block text-secondary"><?= $this->e($review['customerEmail']) ?></small></td><td><?= $this->e($review['tourTitle']) ?></td><td><span class="text-warning"><?php for($i=1;$i<=5;$i++):?><i class="bi <?= $i<=(int)$review['rating']?'bi-star-fill':'bi-star' ?>"></i><?php endfor;?></span></td><td><span class="d-inline-block text-truncate" style="max-width:300px"><?= $this->e($review['comment']) ?></span></td><td><?= date('d/m/Y',strtotime($review['createdAt'])) ?></td><td><div class="d-flex justify-content-end gap-1"><a href="/admin/reviews/show/<?= (int)$review['reviewId'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-eye"></i></a><form action="/admin/reviews/delete/<?= (int)$review['reviewId'] ?>" method="POST" onsubmit="return confirm('Xóa đánh giá này?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$reviews):?><tr><td colspan="7" class="text-center text-secondary py-5">Chưa có đánh giá.</td></tr><?php endif;?></tbody></table></div></div>
<?php $this->stop() ?>
